  ('30e8d963-8308-414e-94fc-d8c7ae0d7167', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '783ea59d-4082-4152-896e-40ff8281ed4e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$चढ़ झंडा फहरा रही थीं और घोषणा पढ़ रही थीं। स्त्रियाँ बहुत बड़ी संख्या में पहुँच गई थीं। प्रायः सबके पास झंडा था। जो वालंटियर गए थे वे अपने स्थान से लाठियाँ पड़ने पर भी हटते नहीं थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-061Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('8a420abb-dc92-42ce-a5ee-0c4d42e1cedb', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '783ea59d-4082-4152-896e-40ff8281ed4e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सुभाष बाबू को पकड़ लिया गया और गाड़ी में बैठाकर लालबाजार लॉकअप में भेज दिया गया। कुछ देर बाद ही स्त्रियाँ जुलूस बनाकर वहाँ से चलीं। साथ में बहुत बड़ी भीड़ इकट्ठी हो गई।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-061Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('d59a978e-0866-4396-9416-c511f450bb16', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '783ea59d-4082-4152-896e-40ff8281ed4e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बीच में पुलिस कुछ ठंडी पड़ी थी, उसने फिर डंडे चलाने शुरू कर दिए। अबकी बार भीड़ ज्यादा होने के कारण बहुत आदमी घायल हुए। धर्मतल्ले के मोड़ पर आकर जुलूस टूट गया और करीब 50-60 स्त्रियाँ वहीं मोड़ पर बैठ गईं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-061Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('f7e06342-1f17-4b5b-ab42-775b87c0a1a8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '783ea59d-4082-4152-896e-40ff8281ed4e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पुलिस ने उनको पकड़कर लालबाजार भेज दिया। स्त्रियों का एक भाग आगे बढ़ा जिसका नेतृत्व विमल प्रतिभा कर रही थीं। उनको बहू बाजार के मोड़ पर रोका गया और वे वहीं मोड़ पर बैठ गईं। आस-पास बहुत बड़ी भीड़ इकट्ठी हो गई, जिस पर पुलिस बीच-बीच में लाठी चलाती थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-061Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('c68baa7b-2cb4-4d69-b260-04e2d8f43388', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '783ea59d-4082-4152-896e-40ff8281ed4e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस प्रकार करीब पौन घंटे के बाद पुलिस की लारी आई और उनको लालबाजार ले जाया गया। और भी कई आदमियों को पकड़ा गया। बृजलाल गोयनका जो कई दिन से अपने साथ काम कर रहा था और दमन जेल में भी अपने साथ था, पकड़ा गया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-061Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('c30c5ebd-fa81-4167-9cda-b43cacdac7c8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '783ea59d-4082-4152-896e-40ff8281ed4e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पहले तो वह झंडा लेकर वंदे मातरम बोलता हुआ मोनुमेंट की ओर इतने जोर से दौड़ा कि अपने आप ही गिर पड़ा और उसे एक अंग्रेजी घुड़सवार ने लाठी मारी फिर पकड़कर कुछ दूर ले जाने के बाद छोड़ दिया। इस पर वह स्त्रियों के जुलूस में शामिल हो गया और वहाँ पर भी उसको छोड़ दिया तब वह दो सौ आदमियों का जुलूस बनाकर लालबाजार गया और वहाँ पर गिरफ्तार हो गया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-061Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('b7e986ff-2732-4750-909c-5c7e1a56c0e6', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '783ea59d-4082-4152-896e-40ff8281ed4e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मंदालसा भी पकड़ी गई थी। उससे मालूम हुआ कि उसको थाने में भी मारा था। सब मिलाकर 105 स्त्रियाँ पकड़ी गई थीं। बाद में रात को नौ बजे सबको छोड़ दिया गया। कलकत्ता में आज तक इतनी स्त्रियाँ एक साथ गिरफ्तार नहीं की गई थीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-061Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('c5d684da-7f51-4d96-abbd-9c96d7fdbf35', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '783ea59d-4082-4152-896e-40ff8281ed4e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$करीब आठ बजे खादी भंडार आए तो कांग्रेस ऑफिस से फोन आया कि यहाँ बहुत आदमी चोट खाकर आए हैं और कई की हालत संगीन है उनके लिए गाड़ी चाहिए। जानकीदेवी के साथ वहाँ गए, बहुत लोगों को चोट लगी हुई थी। डॉक्टर दासगुप्ता उनकी देख-रेख तथा फोटो उतरवा रहे थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-061Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('fef544f2-995e-4524-9ca9-d59a61cbf872', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '783ea59d-4082-4152-896e-40ff8281ed4e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उस समय तक 67 आदमी वहाँ आ चुके थे। बाद में तो 103 तक आ पहुँचे। अस्पताल गए, लोगों को देखने से मालूम हुआ कि 160 आदमी तो अस्पतालों में पहुँचे और जो लोग घरों में चले गए, वे अलग हैं। इस प्रकार दो सौ घायल जरूर हुए हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-061Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('c3c5bd8f-88cc-4f43-bdd7-412d11af9ddb', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '783ea59d-4082-4152-896e-40ff8281ed4e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पकड़े गए आदमियों की संख्या का पता नहीं चला, पर लालबाजार के लॉकअप में स्त्रियों की संख्या 105 थी। आज तो जो कुछ हुआ वह अपूर्व हुआ है। बंगाल के नाम या कलकत्ता के नाम पर कलंक था कि यहाँ काम नहीं हो रहा है वह आज बहुत अंश में धुल गया और लोग सोचने लग गए कि यहाँ भी बहुत सा काम हो सकता है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-061Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
